// Phone controllers as devices (Step 11). Every controller is tracked by its persistent `clientId` (generated by the
// controller page, kept in localStorage) so a phone that reloads or reconnects is recognised as the same device.
// A connection without a clientId (older controller page) falls back to its link connection id.
//
//   const remote = new RemoteSource(link);
//   remote.on('connect', (key, client) => ...);    remote.on('disconnect', (key) => ...);
//   remote.clients          // Map<key, { key, clientId, id, x, y, interact, cancel, t }>  (id = the live link connection id)
//   remote.view(key)        // per-controller source for an InputManager: poll() -> { x, y, interact, cancel, interactTap, cancelTap }
//   remote.sendTo(key, msg) // host -> that phone (e.g. {type:'assign', player, color})
//   remote.count
//
// A stick older than STALE_MS is zeroed (a lost connection can't cause a runaway); held buttons expire after BUTTON_STALE_MS
// (controllers heartbeat every 100 ms while anything is held). Button down-edges are latched (interactTap / cancelTap)
// so a tap that comes and goes between two frames still counts. When the same clientId connects twice (reload before
// the old connection timed out) the newest connection wins and the stale one's events are ignored.
const STALE_MS = 500;
const BUTTON_STALE_MS = 1500;

const keyFor = (id, clientId) => (clientId ? `c-${clientId}` : `n-${id}`);

export class RemoteSource {
  constructor(link) {
    this.name = 'remote';
    this.analog = true;
    this.link = link;
    this.clients = new Map();          // key -> client state
    this._byId = new Map();            // link connection id -> key
    this._views = new Map();
    this._handlers = { connect: [], disconnect: [] };

    link.on('controller-connected', (id, clientId) => {
      const key = keyFor(id, clientId);
      let c = this.clients.get(key);
      const isNew = !c;
      if (!c) {
        c = { key, clientId: clientId || null, id, x: 0, y: 0, interact: false, cancel: false, t: performance.now(), tapI: false, tapC: false };
        this.clients.set(key, c);
      } else {
        c.id = id;                     // reconnect: newest connection takes over
        c.x = c.y = 0; c.interact = c.cancel = false;
        c.t = performance.now();
      }
      this._byId.set(id, key);
      this._emit('connect', key, c, isNew);
    });
    link.on('controller-disconnected', (id) => {
      const key = this._byId.get(id);
      this._byId.delete(id);
      if (!key) return;
      const c = this.clients.get(key);
      if (!c || c.id !== id) return;   // a stale connection of a phone that already reconnected
      this.clients.delete(key);
      this._emit('disconnect', key);
    });
    link.on('input', (m) => {
      let key = this._byId.get(m.id);
      if (!key) {                      // input before we saw the connect event (shouldn't happen): adopt it
        key = keyFor(m.id, m.clientId);
        this._byId.set(m.id, key);
        if (!this.clients.has(key)) {
          const c = { key, clientId: m.clientId || null, id: m.id, x: 0, y: 0, interact: false, cancel: false, t: 0, tapI: false, tapC: false };
          this.clients.set(key, c);
          this._emit('connect', key, c, true);
        }
      }
      const p = this.clients.get(key);
      if (!p || p.id !== m.id) return;
      if (m.interact && !p.interact) p.tapI = true;
      if (m.cancel && !p.cancel) p.tapC = true;
      p.x = Number(m.x) || 0;
      p.y = Number(m.y) || 0;
      p.interact = !!m.interact;
      p.cancel = !!m.cancel;
      p.t = performance.now();
    });
  }

  on(type, fn) { if (this._handlers[type]) this._handlers[type].push(fn); return this; }

  _emit(type, ...args) {
    for (const fn of this._handlers[type]) { try { fn(...args); } catch (e) { console.error(e); } }
  }

  get count() { return this.clients.size; }

  sendTo(key, msg) {
    const c = this.clients.get(key);
    if (!c || !this.link.sendTo) return false;
    return this.link.sendTo(c.id, msg);
  }

  /** Test helper: inject state for a fake controller as if its phone had sent it. */
  inject(key, state) {
    let c = this.clients.get(key);
    if (!c) {
      c = { key, clientId: key.replace(/^c-/, ''), id: -1, x: 0, y: 0, interact: false, cancel: false, t: 0, tapI: false, tapC: false, fake: true };
      this.clients.set(key, c);
      this._emit('connect', key, c, true);
    }
    if (state.interact && !c.interact) c.tapI = true;
    if (state.cancel && !c.cancel) c.tapC = true;
    c.x = state.x || 0; c.y = state.y || 0; c.interact = !!state.interact; c.cancel = !!state.cancel;
    c.t = performance.now();
    return c;
  }

  /** Test helper: drop a fake controller. */
  eject(key) {
    if (this.clients.delete(key)) this._emit('disconnect', key);
  }

  view(key) {
    let v = this._views.get(key);
    if (v) return v;
    const src = this;
    v = {
      name: 'remote',
      analog: true,
      poll() {
        const p = src.clients.get(key);
        const out = { x: 0, y: 0, interact: false, cancel: false, interactTap: false, cancelTap: false };
        if (!p) return out;
        const now = performance.now();
        const fresh = p.fake ? true : now - p.t <= STALE_MS;
        if (fresh) { out.x = p.x; out.y = p.y; }
        if (p.fake || now - p.t <= BUTTON_STALE_MS) { out.interact = p.interact; out.cancel = p.cancel; }
        out.interactTap = p.tapI; out.cancelTap = p.tapC;
        out.interact = out.interact || p.tapI;
        out.cancel = out.cancel || p.tapC;
        p.tapI = p.tapC = false;
        return out;
      },
    };
    this._views.set(key, v);
    return v;
  }
}
